// ShadowLens - Event Processor with DLQ & Retry Logic
// Requirement 1: Compliance & Business Reality (3 retries before DLQ)
// Requirement 2: Observability (Append exact error, timestamp, and retry count)
// Requirement 3: Replayability (Output split 2 arrays: [0] Success, [1] DLQ nested payload)

const successItems = [];
const dlqItems = [];
const MAX_RETRIES = 3;

// Simulate validation of privacy consent logs
function processPayload(payload) {
  if (!payload.userId || !payload.consentState || payload.simulateFail === true) {
      throw new Error('Validation Failed: Missing critical fields (userId, consentState) or corrupted data payload.');
  }
  // Return successfully processed log
  return { 
    ...payload, 
    processedAt: new Date().toISOString(), 
    status: 'success' 
  };
}

// Map through all incoming batch items
for (const item of $input.all()) {
  const payload = item.json;

  let retryCount = 0;
  let processingSuccess = false;
  let lastError = null;

  // Attempt processing, allowing up to MAX_RETRIES
  while (retryCount < MAX_RETRIES && !processingSuccess) {
    try {
      const processedData = processPayload(payload);

      // If successful, queue for array [0]
      successItems.push({ json: processedData });
      processingSuccess = true;
    } catch (error) {
      retryCount++;
      lastError = error;
      // Loop continues if retryCount < MAX_RETRIES
    }
  }

  // If still failing after MAX_RETRIES, send to DLQ
  if (!processingSuccess) {
    dlqItems.push({
      json: {
        errorContext: {
          errorMessage: lastError.message,
          timestamp: new Date().toISOString(),
          retryCount: retryCount,
        },
        // The original payload remains unmodified for clean replayability!
        originalPayload: payload
      }
    });
  }
}

// Cleanly separate outputs: 
// main[0][0] -> Success Database
// main[0][1] -> Quarantine Database
return [successItems, dlqItems];
